// Gather results from all three branches
const zammadData = $('Fetch Open Tickets (Zammad)').first().json;
const erpData = $('Fetch Overdue Invoices (ERPNext)').first().json;
const trmmData = $('Fetch Offline Agents (TRMM)').first().json;

// Parse tickets
const tickets = Array.isArray(zammadData) ? zammadData : (zammadData.tickets || []);
const p1 = tickets.filter(t => t.priority_id >= 3);
const p2 = tickets.filter(t => t.priority_id === 2);
const p3 = tickets.filter(t => t.priority_id === 1);

// Find tickets open > 2 hours (P1 SLA breach risk)
const now = new Date();
const slaAtRisk = p1.filter(t => {
  const created = new Date(t.created_at);
  const hrs = (now - created) / 3600000;
  return hrs > 1.5; // warn at 1.5hr for 2hr SLA
});

// Parse invoices
const invoices = erpData.data || [];
const today = new Date().toISOString().split('T')[0];
const overdue = invoices.filter(i => i.due_date < today);
const dueToday = invoices.filter(i => i.due_date === today);
const totalOwed = invoices.reduce((s, i) => s + (i.outstanding_amount || 0), 0);

// Parse TRMM agents
const agents = Array.isArray(trmmData) ? trmmData : [];
const offline = agents.filter(a => !a.status || a.status === 'offline' || a.overdue);

// Build email body
const lines = [];
const date = new Date().toLocaleDateString('en-US', {weekday:'long', month:'long', day:'numeric', timeZone:'America/Chicago'});

lines.push(`<h2 style="color:#1A3D6B;border-bottom:2px solid #1A3D6B;padding-bottom:8px">☀️ Kecktech Morning Briefing — ${date}</h2>`);

// TICKETS
lines.push(`<h3 style="color:#2E7D8C">🎧 Support Tickets</h3>`);
if (tickets.length === 0) {
  lines.push(`<p style="color:green">✅ No open tickets — clear slate!</p>`);
} else {
  lines.push(`<p><strong>Open:</strong> ${tickets.length} total &nbsp;|&nbsp; P1: ${p1.length} &nbsp;|&nbsp; P2: ${p2.length} &nbsp;|&nbsp; P3: ${p3.length}</p>`);
  if (slaAtRisk.length > 0) {
    lines.push(`<p style="color:#C0392B"><strong>⚠️ SLA AT RISK (P1 &gt;1.5hr):</strong></p><ul>`);
    slaAtRisk.forEach(t => lines.push(`<li>#${t.number} — ${t.title} (${t.customer_id || 'unknown'})</li>`));
    lines.push(`</ul>`);
  }
  if (p1.length > 0) {
    lines.push(`<p><strong>P1 Critical:</strong></p><ul>`);
    p1.slice(0,5).forEach(t => lines.push(`<li><a href="https://tickets.kecktech.net/#ticket/zoom/${t.id}">#${t.number}</a> — ${t.title}</li>`));
    lines.push(`</ul>`);
  }
}

// INVOICES
lines.push(`<h3 style="color:#2E7D8C">💰 Accounts Receivable</h3>`);
if (invoices.length === 0) {
  lines.push(`<p style="color:green">✅ No outstanding invoices</p>`);
} else {
  lines.push(`<p><strong>Total Outstanding:</strong> $${totalOwed.toLocaleString('en-US', {minimumFractionDigits:2})}</p>`);
  if (overdue.length > 0) {
    lines.push(`<p style="color:#C0392B"><strong>⚠️ Overdue (${overdue.length}):</strong></p><ul>`);
    overdue.slice(0,5).forEach(i => lines.push(`<li>${i.customer} — ${i.name} — $${i.outstanding_amount} (due ${i.due_date})</li>`));
    lines.push(`</ul>`);
  }
  if (dueToday.length > 0) {
    lines.push(`<p><strong>Due Today (${dueToday.length}):</strong></p><ul>`);
    dueToday.forEach(i => lines.push(`<li>${i.customer} — ${i.name} — $${i.outstanding_amount}</li>`));
    lines.push(`</ul>`);
  }
}

// TRMM
lines.push(`<h3 style="color:#2E7D8C">🖥️ Device Health (TRMM)</h3>`);
if (offline.length === 0) {
  lines.push(`<p style="color:green">✅ All monitored agents online</p>`);
} else {
  lines.push(`<p style="color:#C0392B"><strong>⚠️ ${offline.length} agent(s) offline:</strong></p><ul>`);
  offline.slice(0,10).forEach(a => lines.push(`<li>${a.hostname || a.agent_id} — ${a.client_name || 'unknown client'}</li>`));
  lines.push(`</ul>`);
}

// QUICK LINKS
lines.push(`<hr style="margin:20px 0">`);
lines.push(`<p style="font-size:12px;color:#64748b">`);
lines.push(`<a href="https://dashboard.kecktech.net">Dashboard</a> &nbsp;|&nbsp; `);
lines.push(`<a href="https://tickets.kecktech.net">Tickets</a> &nbsp;|&nbsp; `);
lines.push(`<a href="https://ops.kecktech.net/app/sales-invoice">Invoices</a> &nbsp;|&nbsp; `);
lines.push(`<a href="https://rmm.kecktech.net">TRMM</a>`);
lines.push(`</p>`);

return [{ json: { html: lines.join('\n'), ticketCount: tickets.length, overdueCount: overdue.length, offlineCount: offline.length } }];
